#X3D V4.1 utf8 X_ITE V16.5.0

PROFILE Full

COMPONENT Sound : 2

Viewpoint {
  position 0 0 0
}

Sound {
  location 0 0 -5
  minBack 20
  minFront 20
  maxBack 40
  maxFront 40
  source DEF O AudioClip {
    url "media/tone48k-stereo.wav"
    loop TRUE
    startTime 946684800.048
    resumeTime 946684800.272
    pauseTime 946684800.176
    stopTime 946684800.368
  }
}

DEF T TimeSensor {
  cycleInterval 0.5
  loop TRUE
}

DEF S Script {
  inputOnly      SFTime  set_time
  outputOnly     SFTime  start
  initializeOnly SFInt32 n 49

  url "javascript:
function set_time (value) { if (++ n === 12) start = value; }
"
}

DEF K Script {
  initializeOnly SFNode  o USE O
  inputOnly      SFTime  set_time
  initializeOnly SFInt32 n 49

  url "ecmascript:
function set_time (value) { ++ n;
   if (n === 20) o.pauseTime = value;
   if (n === 26) o.resumeTime = value;
   if (n === 32) o.stopTime = value;
}
"
  directOutput TRUE
}

DEF PO Script {
  inputOnly SFBool a
  inputOnly SFTime d
  inputOnly SFTime e
  inputOnly SFBool p

  url "javascript:
function a (v, t) { print ('O active ' + v + ' ' + t); }
function d (v, t) { print ('O duration ' + v + ' ' + t); }
function e (v, t) { print ('O elapsed ' + v + ' ' + t); }
function p (v, t) { print ('O paused ' + v + ' ' + t); }
"
}

ROUTE T.time TO S.set_time
ROUTE S.start TO O.set_startTime
ROUTE T.time TO K.set_time
ROUTE O.isActive TO PO.a
ROUTE O.duration_changed TO PO.d
ROUTE O.elapsedTime TO PO.e
ROUTE O.isPaused TO PO.p
